<?php
require_once __DIR__ . '/includes/functions.php';
if ($_SERVER['REQUEST_METHOD']==='POST') {
    verify_csrf(); $id=filter_input(INPUT_POST,'product_id',FILTER_VALIDATE_INT); $action=$_POST['action']??'';
    if($id){ $current=(int)(cart()[$id]??0); if($action==='add') $_SESSION['cart'][$id]=$current+1; elseif($action==='set'){ $qty=max(0,min(20,(int)($_POST['quantity']??0))); if($qty) $_SESSION['cart'][$id]=$qty; else unset($_SESSION['cart'][$id]); } elseif($action==='remove') unset($_SESSION['cart'][$id]); }
    header('Location: cart.php'); exit;
}
$items=[]; if(cart()){ $ids=array_keys(cart());$marks=implode(',',array_fill(0,count($ids),'?'));$s=db()->prepare("SELECT p.*, (SELECT image_path FROM product_images WHERE product_id=p.id ORDER BY id LIMIT 1) image FROM products p WHERE p.id IN ($marks)");$s->execute($ids);foreach($s as $p){$p['qty']=min((int)$p['stock'],(int)cart()[$p['id']]);if($p['qty'])$items[]=$p;} }
$page_title='Your cart'; require 'includes/header.php';
?><section class="section"><div class="container"><div class="section-title"><div><p class="eyebrow">Your selection</p><h1>Shopping cart</h1></div></div><?php if(!$items): ?><div class="empty">Your cart is empty. <a href="index.php#shop">Browse phones</a>.</div><?php else: ?><div class="cart-layout"><div class="cart-items"><?php foreach($items as $p): ?><article class="cart-item"><img src="<?=image_url($p['image'])?>" alt="<?=e($p['name'])?>"><div><h3><?=e($p['name'])?></h3><p><?=e($p['brand'])?> · <?=e($p['storage'])?></p><strong><?=money($p['price'])?></strong></div><form method="post" class="qty-form"><input type="hidden" name="csrf" value="<?=csrf_token()?>"><input type="hidden" name="product_id" value="<?=$p['id']?>"><input type="number" min="1" max="<?=max(1,$p['stock'])?>" name="quantity" value="<?=$p['qty']?>"><button name="action" value="set">Update</button><button class="danger" name="action" value="remove">Remove</button></form></article><?php endforeach ?></div><aside class="order-summary"><h2>Order summary</h2><p>Subtotal <strong><?=money(cart_total())?></strong></p><p>Delivery is confirmed during checkout.</p><a class="button primary" href="checkout.php">Proceed to checkout</a></aside></div><?php endif ?></div></section><?php require 'includes/footer.php'; ?>
